previewCss:
.darma-loader-darma-b16-microscope-focus { --accent: var(--loader-color, #0d9488); --accent-2: var(--loader-secondary-color, #a7f3d0); width: var(--loader-size, 116px); height: var(--loader-size, 116px); position: relative; }
.darma-loader-darma-b16-microscope-focus .darma-loader-darma-b16-microscope-focus__rim { position: absolute; left: 8%; top: 8%; width: 84%; height: 84%; border-radius: 50%; box-shadow: inset 0 0 0 4px color-mix(in srgb, var(--accent) 55%, transparent), inset 0 0 0 10px color-mix(in srgb, var(--accent) 15%, transparent); }
.darma-loader-darma-b16-microscope-focus .darma-loader-darma-b16-microscope-focus__field { position: absolute; left: 14%; top: 14%; width: 72%; height: 72%; border-radius: 50%; overflow: hidden; background: radial-gradient(circle, color-mix(in srgb, var(--accent-2) 35%, transparent), transparent 72%); animation: darma-loader-darma-b16-microscope-focus-scope-focus calc(var(--loader-speed, 1s) * 2.8) ease-in-out infinite; }
.darma-loader-darma-b16-microscope-focus i { position: absolute; border-radius: 50% 40% 55% 45%; background: color-mix(in srgb, var(--accent) 75%, transparent); animation: darma-loader-darma-b16-microscope-focus-scope-swim calc(var(--loader-speed, 1s) * 5) ease-in-out infinite; }
.darma-loader-darma-b16-microscope-focus i:nth-of-type(1) { left: 18%; top: 24%; width: 26%; height: 20%; }
.darma-loader-darma-b16-microscope-focus i:nth-of-type(2) { left: 52%; top: 52%; width: 20%; height: 26%; animation-delay: calc(var(--loader-speed, 1s) * -1.7); }
.darma-loader-darma-b16-microscope-focus i:nth-of-type(3) { left: 30%; top: 62%; width: 16%; height: 14%; animation-delay: calc(var(--loader-speed, 1s) * -3.4); }
.darma-loader-darma-b16-microscope-focus .darma-loader-darma-b16-microscope-focus__knob { position: absolute; right: 0; top: 42%; width: 12%; height: 16%; border-radius: 3px; background: repeating-linear-gradient(#94a3b8 0 22%, #475569 0 44%); animation: darma-loader-darma-b16-microscope-focus-scope-knob calc(var(--loader-speed, 1s) * 2.8) ease-in-out infinite; }
@keyframes darma-loader-darma-b16-microscope-focus-scope-focus { 0%, 100% { filter: blur(5px); opacity: .55; } 46%, 62% { filter: blur(0); opacity: 1; } }
@keyframes darma-loader-darma-b16-microscope-focus-scope-swim { 0%, 100% { transform: translate(0, 0) rotate(0deg); } 50% { transform: translate(18%, -14%) rotate(140deg); } }
@keyframes darma-loader-darma-b16-microscope-focus-scope-knob { 0%, 100% { transform: translateY(0); } 46%, 62% { transform: translateY(-40%); } }

